    "title": "Barra parcialmente submersa",
    "text": "Uma barra homogênea e fina de seção reta circular A e comprimento L tem uma de suas extremidades fixas a uma articulação, podendo girar sem atrito. As figuras abaixo mostram duas situações nas quais a barra se encontra em equilíbrio estático. No primeiro caso, a barra está parcialmente mergulhada em uma cuba preenchida com um líquido, de forma que 25% de seu comprimento ficam submersos, conforme a figura (a). No segundo caso, um objeto pontual, com 50% da massa da barra, está fixado em sua extremidade livre, como ilustra a figura (b). Assinale a alternativa correspondente ao novo comprimento submerso da barra na situação exposta na figura (b).",
