    "title": "Gás ideal, êmbolo e mola",
    "text": "Um recipiente de paredes diatérmicas é dividido ao meio por um êmbolo de área A. O lado esquerdo do êmbolo é conectado ao recipiente por uma mola ideal de constante elástica k, em uma região onde há vácuo. No lado direito do êmbolo, há um gás ideal a uma pressão inicial P₀. Então, uma quantidade Q de calor é transferida a esse gás por um processo reversível e isotérmico. Assinale a alternativa que fornece a diferença entre o comprimento natural da mola e o seu comprimento ao final do processo descrito.",
