    "text": "O efeito Raman ocorre quando há o espalhamento inelástico da luz pela matéria, de forma que o fóton espalhado contém um pequeno decremento ou incremento de um quantum de energia relacionado a transições entre modos vibracionais na matéria. Em um experimento realizado a temperatura ambiente, um fóton incidente de comprimento de onda de 620 nm é espalhado por um cristal, resultando em um fóton espalhado com comprimento de onda de 590 nm. Suponha que esse mesmo cristal, submetido à mesma radiação incidente, seja mantido a uma temperatura próxima ao zero absoluto, de tal forma que somente um modo vibracional esteja envolvido no espalhamento inelástico. Assinale a alternativa que corresponde ao comprimento de onda do fóton espalhado.",
