    "title": "Equilíbrio de um disco acoplado a uma mola",
    "text": "Um disco de raio R com centro em O pode girar livremente em um plano horizontal sem atrito em torno de um eixo fixo que passa por O. Uma mola de comprimento natural L tem uma das suas extremidades articuladas a um ponto fixo na parede. Este ponto está localizado a uma distância L do ponto O. A outra extremidade está articulada à borda do disco, em uma posição cujo movimento será analisado a seguir. Inicialmente, a mola se encontra em orientação perpendicular à parede e seu comprimento está reduzido a x = L − R, como mostra a figura. Considere que os pontos A e B são pontos fixos do espaço e que R < L. A seguir, são feitas algumas afirmações sobre esse sistema. 1. O sistema tem apenas dois pontos de equilíbrio, A e B, sendo ambos instáveis. 2. Se um pequeno torque impulsivo for aplicado ao disco, este último continuará completando voltas indefinidamente, contanto que não haja nenhuma dissipação de energia. 4. Se um pequeno torque impulsivo for aplicado ao disco, este pode não completar uma volta se a sua massa for muito grande e a constante elástica for muito pequena, mesmo sem haver dissipação de energia. 8. Seja C um ponto fixo no espaço a uma distância R de O. Se |∠AOC| < 30°, C nunca será um ponto de equilíbrio estável. Assinale a alternativa que contém a soma dos números correspondentes às afirmações verdadeiras.",
