    "title": "Ola de estádio e intensidade sonora",
    "text": "Em eventos esportivos, é comum que os espectadores realizem a coreografia da “ola”. Os participantes erguem seus braços e os abaixam logo em seguida, em fileiras sucessivas, criando o efeito visual de uma onda. Os espectadores gritam juntos “ola” seguindo a propagação da onda. Assuma que a distância D entre as cadeiras e o tempo τ de deslocamento de braço são constantes. Assuma que um participante só inicia o movimento da “ola” quando o participante na fileira ao lado o encerra. A respeito da situação física descrita, são feitas as seguintes afirmações: I. Se um estádio com 30.000 pessoas gritando resulta em um ruído sonoro de 90 dB, o ruído de 60.000 pessoas gritando é de aproximadamente 93 dB. II. A onda resultante da coreografia é longitudinal. III. A velocidade da onda é diretamente proporcional a τ e inversamente proporcional a D. Sobre as afirmações I, II e III pode-se afirmar que",
