    "text": "Considere um arranjo experimental, representado na figura, em que um ímã pode se movimentar ao longo das retas AB ou A′B′, sempre com velocidade constante (v ≪ c). Uma espira retangular de auto-indutância desprezível é posicionada perpendicularmente a AB. Pelo centro da espira, o ponto P, passam as retas AB e A′B′. A corrente elétrica na espira, observada desde a perspectiva de um observador no ponto A, é positiva, por convenção, se estiver no sentido horário. O polo norte do ímã sempre aponta ou para A ou para A′. A respeito da situação física descrita, são feitas as seguintes afirmações: I. Quando o ímã se desloca de A para P, a corrente na espira é negativa. II. No momento em que o centro do ímã passa pelo ponto P, a corrente na espira é zero. III. Durante a passagem do ímã de A para B, haverá dois picos de corrente medidos. IV. Quando o ímã passa por A′B′, a corrente máxima na espira é maior do que a corrente máxima quando o ímã passa por AB. Das afirmações I a IV, acima destacadas, estão corretas",
