    "title": "Múon relativístico na atmosfera",
    "text": "A todo instante, raios cósmicos atingem a atmosfera terrestre e colidem com núcleos atômicos. Dessas interações, é formada uma cascata de partículas que permeia nossa atmosfera. Muitas dessas partículas são instáveis, o que significa que, após determinado intervalo de tempo (tempo de vida), elas decaem. Seja um múon criado a uma altitude de 100 km e que se movimenta com uma velocidade vertical em direção ao solo de 0,9999c. Sabendo que seu tempo de vida, em repouso, é de 2,2 μs, a mínima altitude que essa partícula atinge, aproximadamente, é de",
