    "title": "Perseguição de alvo móvel por dois mísseis",
    "text": "Um sistema de defesa aérea testa, separadamente, dois mísseis contra alvos móveis que se deslocam com velocidade v⃗a constante ao longo de uma reta distante de d do ponto de lançamento dos mísseis. Para atingir o alvo, o míssil 1 executa uma trajetória retilínea, enquanto o míssil 2, uma trajetória com velocidade sempre orientada para o alvo. A figura ilustra o instante de disparo de cada míssil, com o alvo passando pela origem do sistema de coordenadas xy. Sendo os módulos das velocidades dos mísseis iguais entre si, maiores que va e mantidos constantes, considere as seguintes afirmações: I. Os intervalos de tempo entre o disparo e a colisão podem ser iguais para ambos os mísseis. II. Para que o míssil 1 acerte o alvo é necessário que o módulo da componente y de sua velocidade seja igual a va. III. Desde o disparo até a colisão, o míssil 2 executa uma trajetória curva de concavidade positiva com relação ao sistema xy. Considerando V como verdadeira e F como falsa, as afirmações I, II e III são, respectivamente,",
