    "title": "Difração de raios X e elétrons",
    "text": "Com um certo material, cujas camadas atômicas interdistam de uma distância d, interage um feixe de radiação queé detectado em um ângulo θ conforme a figura. Tal experimentoé realizado em duas situações: (I) o feixeé de raios X monocromáticos, com sua intensidade de radiação medida por um detector, resultando numa distribuição de intensidade em função de θ, com valor máximo para θ = α, e (II) o feixeé composto por elétrons monoenergéticos, com a contagem do número de elétrons por segundo para cadaângulo medido, resultando no seu valor máximo para θ = β. Assinale a opção com possíveis mudanças que implicam a alteração simultânea dosângulos α e β medidos.",
