    "text": "O módulo de Young de um material mede sua resistência a deformações causadas por esforços externos. Numa parede vertical, encontra-se engastado um sólido maciço de massa específica ρ e módulo de Young E, em formato de paralelepípedo reto, cujas dimensões são indicadas na figura. Com base nas correlações entre grandezas físicas, assinale a alternativa que melhor expressa a deflexão vertical h sofrida pela extremidade livre do sólido pela ação do seu próprio peso.",
