    "title": "Satélites com o mesmo semieixo maior",
    "text": "Considere dois satélites artificiais S e T em torno da Terra. S descreve uma órbita elíptica com semieixo maior a, e T, uma órbita circular de raio a, com os respectivos vetores posição rS e rT com origem no centro da Terra. É correto afirmar que",
