    "title": "Esfera tampando um orifício submerso",
    "text": "Uma esfera de massa m tampa um buraco circular de raio r no fundo de um recipiente cheio de água de massa específica ρ. Baixando-se lentamente o nível da água, num dado momento a esfera se desprende do fundo do recipiente. Assinale a alternativa que expressa a altura h do nível de água para que isto aconteça, sabendo que o topo da esfera, a uma altura a do fundo do recipiente, permanece sempre coberto de água.",
