    "year": 2014,
    "number": 4,
    "topic": "Óptica",
    "level": "Difícil",
    "title": "Anéis de Newton em lente plano-côncava",
    "text": "Sobre uma placa de vidro planaé colocada uma lente plano-côncava, com 1,50 deíndice de refração e concavidade de 8,00 m de raio voltada para baixo. Com a lente iluminada perpendicularmente de cima por uma luz de comprimento de onda 589 nm (no ar), aparece um padrão de interferência com um ponto escuro central circundado por anéis, dos quais 50 são escuros, inclusive o mais externo na borda da lente. Este padrão de interferência aparece devido ao filme de ar entre a lente e a placa de vidro (como esquematizado na figura). A espessura da camada de ar no centro do padrão de interferência e a distância focal da lente são, respectivamente,",
