    "text": "Considere um capacitor de placas paralelas ao plano yz tendo um campo elétrico de intensidade E entre elas, medido por um referencial S em repouso em relação ao capacitor. Dois outros referenciais, S' e S'', que se movem com velocidade de módulo v constante em relação a S nas direções x e y, nesta ordem, medem as respectivas intensidades E' e E'' dos campos elétricos entre as placas do capacitor. Sendo γ = 1/√[1 - (v/c)²], pode-se dizer que E'/E e E''/E são, respectivamente, iguais a",
