    "title": "Proposições de eletrostática",
    "text": "Considere as afirmações a seguir: I. Em equilíbrio eletrostático, uma superfície metálicaé equipotencial. II. Um objeto eletrostaticamente carregado induz uma carga uniformemente distribuída numa superfície metálica próxima quando em equilíbrio eletrostático. III. Uma carga negativa desloca-se da região de maior para a de menor potencial elétrico. IV. Énulo o trabalho para se deslocar uma carga teste do infinito até o ponto médio entre duas cargas pontuais de mesmo módulo e sinais opostos. Destas afirmações, é (são) correta(s) somente",
