    "title": "Corrente induzida em anel e ímã",
    "text": "Considere um ímã cilíndrico vertical com o polo norte para cima, tendo um anel condutor posicionado acima do mesmo. Um agente externo imprime um movimento ao anel que, partindo do repouso, desce verticalmente em torno do ímã e atinge uma posição simétrica à original, iniciando logo em seguida um movimento ascendente e retornando à posição inicial em repouso. Considerando o eixo de simetria do anel sempre coincidente com o do ímã e sendo positiva a corrente no sentido anti-horário, visto por um observador de cima, o gráfico que melhor representa o comportamento da corrente induzida i no anel é",
