    "text": "Um circuito elétrico com dois pares de terminais é conhecido como quadripolo. Para um quadripolo passivo, as tensões medidas em cada par de terminais podem ser expressas em função das correntes mediante uma matriz de impedância Z = [[z₁₁, z₁₂], [z₂₁, z₂₂]], de tal forma que [v₁, v₂]ᵀ = Z[i₁, i₂]ᵀ. Dos quadripolos propostos nas alternativas, assinale aquele cuja matriz de impedância seja [[4 Ω, 2 Ω], [2 Ω, 3 Ω]].",
