    "title": "Efeito Doppler em sistema binário",
    "text": "Um sistema binário é formado por duas estrelas esféricas de respectivas massas m e M, cujos centros distam d entre si, cada qual descrevendo um movimento circular em torno do centro de massa desse sistema. Com a estrela de massa m na posição mostrada na figura, devido ao efeito Doppler, um observador T da Terra detecta uma raia do espectro do hidrogênio, emitida por essa estrela, com uma frequência f ligeiramente diferente da sua frequência natural f₀. Considere a Terra em repouso em relação ao centro de massa do sistema e que o movimento das estrelas ocorre no mesmo plano de observação. Sendo as velocidades das estrelas muito menores que c, assinale a alternativa que explicita o valor absoluto de (f - f₀)/f₀. Se necessário, utilize (1 + x)ⁿ ≈ 1 + nx para x ≪ 1.",
