    "level": "Difícil",
    "title": "Seta do tempo",
    "text": "Diferentemente da dinâmica newtoniana, que não distingue passado e futuro, a direção temporal tem papel marcante no nosso dia-a-dia. Assim, por exemplo, ao aquecer uma parte de um corpo macroscópico e o isolarmos termicamente, a temperatura deste se torna gradualmente uniforme, jamais se observando o contrário, o que indica a direcionalidade do tempo. Diz-se então que os processos macroscópicos são irrevers íveis, evoluem do passado para o futuro e exibem o que o famoso cosmólogo Sir Arthur Eddington denominou de seta do tempo. A lei física que melhor traduz o tema do texto é",
