    "text": "Num experimento de efeito fotoelétrico, ilumina-se um metal com luz proveniente de átomos de hidrogênio que transitam do estado n para o fundamental. A função trabalho φ do metal é igual à metade da energia de ionização do hidrogênio, cuja energia do estado n é Eₙ = E₁/n². Considere: I. A energia cinética máxima é E𝒄 = E₁/n² − E₁/2. II. A função trabalho é φ = −E₁/2. III. A energia cinética máxima dos elétrons aumenta com a frequência da luz incidente a partir da frequência mínima de emissão. Assinale a alternativa verdadeira.",
