    "text": "Uma lua de massa m de um planeta distante, de massa M ≫ m, descreve uma órbita el íptica com semieixo maior a e semieixo menor b, perfazendo um sistema de energia E. A lei das áreas de Kepler relaciona a velocidade v da lua no apogeu com sua velocidade v′ no perigeu, isto é,v′(a − e) = v (a + e), em que e é a medida do centro ao foco da elipse. Nessas condições, podemos afirmar que",
