    "text": "Considere um segmento de reta que liga o centro de qualquer planeta do sistema solar ao centro do Sol. De acordo com a 2 a Lei de Kepler, tal segmento percorre áreas iguais em tempos iguais. Considere, então, que em dado instante deixasse de existir o efeito da gravitação entre o Sol e o planeta. Assinale a alternativa correta.",
