    "text": "Desde os idos de 1930, observações astronômicas indicam a existência da chamada matéria escura. Tal matéria não emite luz, mas a sua presença é inferida pela influência gravitacional que ela exerce sobre o movimento de estrelas no interior de galáxias. Supo nha que, numa galáxia, possa ser removida sua matéria escura de massa espec íficaρ > 0, que se encontra uniformemente distribu ída. Suponha tam bém que no centro dessa galáxia haja um buraco negro de massa M, em volta do qual uma estrela de massa m descreve uma órbita circular. Considerando órbitas de mesmo raio na presença e na ausência de matéria escura, a respeito da força gravitacional resultante⃗F exercida sobre a estrela e seu efeito sobre o movimento desta, pode-se afirmar que",
